// Hydration index — record JAH-GGNS-SMARTBOTTLE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"capacity_ml": 750, "battery_days": 30, "price_usd": 80};
var value = (m.capacity_ml*m.battery_days/m.price_usd);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGNS-SMARTBOTTLE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGNS-SMARTBOTTLE-000001|' + value.toFixed(2) + ' hydration index');

